-- V188: 10 объёмных лекций Чертогов Мимира (week 125-134)
-- Написано вручную, потому что cron генерации не успевал из-за AI-баланса и обрезанного JSON.
-- Каждая лекция: 14-18 блоков, 12+ вопросов, 5-7 минут чтения.
-- Темы — прикладные для рабочих нефтегаза/стройки (СИЗ, такелаж, питание, финграмотность).

BEGIN;

-- ════════════════════════════════════════════════════════════════════════════
-- WEEK 125: Электросварка — режимы, прохождения, дефекты шва
-- ════════════════════════════════════════════════════════════════════════════

WITH lesson AS (
  INSERT INTO academy_lessons
    (week_number, saga, title, cover_icon, cover_color, estimated_minutes, tags,
     status, generated_by, blocks, is_mandatory, published_at, release_monday)
  VALUES (
    125, 'Мастерство ремесла', 'Электросварка: корень, заполнение, лицевой',
    '⚡', '#1e2840', 7,
    ARRAY['сварка','шов','дефекты','ремесло'],
    'published', 'manual',
    $blocks$[
      {"type":"cover","icon":"⚡","title":"Электросварка: корень, заполнение, лицевой","subtitle":"Три прохода, которые держат миллион тонн"},
      {"type":"intro","text":"Сварной шов — это не «прилепить и готово». Это три-четыре прохода металла, каждый со своей задачей. Корневой проход держит конструкцию изнутри, заполняющий даёт прочность, лицевой — красоту и герметичность. Ошибка на любом из них рушит всё. На промысле сварной шов на трубе диаметром 1420 мм может выдерживать давление 100 атм — а это сила, равная весу пятиэтажного дома на каждый квадратный метр. Поэтому каждый сантиметр шва записан, отрентгенен и подписан мастером лично."},
      {"type":"text_block","title":"Что такое корневой проход и почему он важнее всего","text":"Корневой проход (или просто «корень») — это первый слой металла, который заполняет зазор между свариваемыми деталями. Зазор делают 2-4 мм специально, чтобы электрод прожог обе кромки насквозь и сплавил их в одно целое. Если корень не проварен — на стыке остаётся щель, в которую под давлением пойдёт нефть или газ. Корень варят электродом меньшего диаметра (2.5-3.2 мм) на пониженных токах: 70-110 А для электродов с основным покрытием типа УОНИИ-13/55. Скорость — медленная, 8-12 см/мин: важно, чтобы металл успел проплавиться насквозь, а не лёг сверху."},
      {"type":"icon_grid","title":"Три прохода трубы Ø219×8 мм — реальные параметры","items":[
        {"icon":"1️⃣","label":"Корень: УОНИИ-13/55 Ø3.0","desc":"Ток 90-100 А, обратная полярность, скорость 10 см/мин"},
        {"icon":"2️⃣","label":"Заполнение: УОНИИ Ø4.0","desc":"Ток 140-160 А, 2-3 слоя поперёк или ёлочкой, контроль температуры межслойной"},
        {"icon":"3️⃣","label":"Лицевой: УОНИИ Ø4.0","desc":"Ток 130-150 А, ширина в 2 раза больше валика, плавная чешуйка"},
        {"icon":"🌡️","label":"Подогрев перед сваркой","desc":"При толщине от 8 мм и зимой обязателен — газовая горелка до 100-150°C"},
        {"icon":"📏","label":"Зазор между кромками","desc":"2-4 мм для корня, проверяется щупом перед каждым стыком"}
      ]},
      {"type":"text_block","title":"Заполняющие слои — где набирается прочность","text":"После корня шов имеет толщину 2-3 мм — это меньше четверти от полной. Дальше идут заполняющие проходы: их количество зависит от толщины металла. Для трубы 8 мм нужно 2 заполняющих слоя, для 12 мм — уже 3-4. Каждый следующий слой кладут поверх предыдущего, перекрывая на 1/3 ширины. Между слоями обязательно зачистка металлической щёткой или шарошкой — иначе шлак от предыдущего прохода останется внутри. Шлак — это твёрдый стекловидный материал, продукт горения покрытия электрода. Если он остался в шве, его не видно глазом, но рентген покажет тёмные пятна — шлаковые включения, дефект."},
      {"type":"warning","level":"danger","text":"Сварка без подогрева в мороз ниже -15°C — гарантированные трещины. Сталь при минусовой температуре охлаждается слишком быстро, металл шва не успевает выровнять напряжения и рвётся через сутки или прямо при гидроиспытаниях. На каждом промысле есть журнал погоды — сварщик расписывается, что подогрев был проведён. Без этой подписи стык не принимают."},
      {"type":"text_block","title":"Лицевой проход — что видит контролёр","text":"Лицевой проход — это то, что увидит инспектор ВИК (визуально-измерительный контроль). Он должен быть равномерным по ширине (обычно 12-16 мм), чешуйчатость — плавная и однородная. Высота усиления — 1-3 мм над основным металлом, не больше. Если усиление выше 3 мм, в этом месте концентрируется напряжение — шов треснет первым. Кратеры (углубления в конце электрода) на лицевом запрещены: их обязательно заваривают коротким движением назад. Подрезы (углубления вдоль края шва) глубже 0.5 мм — брак, шов вырезается и переваривается."},
      {"type":"steps","title":"Алгоритм сварки одного стыка трубы","items":[
        "Зачистить торцы трубы до металлического блеска шарошкой на 15-20 мм с каждой стороны — ржавчина даёт поры в шве",
        "Выставить зазор 2-4 мм с помощью прихваток (3-4 короткие точки) — фиксируется штангенциркулем",
        "Прогреть зону сварки до 100-150°C, если толщина >8 мм или температура <+5°C — измерять контактным термометром",
        "Варить корень снизу вверх (потолочно-вертикально) электродом Ø2.5-3.0 на токе 90-100 А, скорость 10 см/мин",
        "После корня дать остыть до 100°C, зачистить шлак щёткой и шарошкой — рукой проверять что чисто",
        "Варить заполняющие слои Ø4 мм на 140-160 А, между слоями обязательная зачистка",
        "Лицевой проход — ширина 12-16 мм, ровная чешуйка, высота 1-3 мм над металлом",
        "После сварки оформить клеймо: личный номер сварщика выбивают рядом со швом — это его подпись"
      ]},
      {"type":"text_block","title":"Главные дефекты шва: что увидит рентген","text":"Контроль шва бывает разный: визуальный (ВИК), ультразвуковой (УЗК) и радиографический (рентген). Рентген — самый строгий, он видит то, что не видно глазом. Главные дефекты: поры (округлые пустоты от выгоревших газов — обычно от ржавчины или мокрого электрода), шлаковые включения (тёмные пятна от незачищенного шлака между слоями), непровар (корень не прошёл насквозь — видна светлая линия по центру), трещины (тонкие линии — самый опасный дефект, в работу не допускаются никогда). По ГОСТ 23055-78 шов делится на классы 1-7. Для нефтегаза обычно требуется класс 1-3 — поры до 1 мм допустимы поодиночке, цепочка пор уже брак."},
      {"type":"fact_card","icon":"⚠️","text":"2019 год, Ямал. Сварщик торопился — варил без зачистки между слоями. Через два месяца после ввода в эксплуатацию трубопровод дал течь в этом стыке. Проверка показала: шлаковые включения занимали 30% сечения шва. Утечка нефти 12 тонн в тундру. Сварщика лишили клейма пожизненно, компания заплатила штраф 4.5 млн руб. за экологический ущерб. На брифинге руководитель сказал коротко: «Зачистка шарошкой — 30 секунд. Лишение клейма — на всю жизнь». С тех пор зачистку фиксируют на фото."},
      {"type":"text_block","title":"Электроды: маркировка, хранение, прокалка","text":"Электроды с покрытием бывают трёх типов: основные (Б, типичный пример — УОНИИ-13/55) для ответственных швов, кислые (А) для простых конструкций, рутиловые (Р, типа МР-3) для бытовых задач. На нефтегазе используют только основные. Они дают самый чистый и пластичный шов, но боятся влаги: впитавший воду электрод даст поры. Поэтому открытую пачку нужно использовать за смену или прокалить заново — 250-350°C в течение 1-2 часов в специальной печи. На объект электроды носят в герметичных пеналах-термосах, которые греют сами от 9V батарейки. Без прокалки и пеналов работа на промысле запрещена."},
      {"type":"icon_grid","title":"Маркировка электрода УОНИИ-13/55 — что значат цифры","items":[
        {"icon":"5️⃣","label":"Тип Э50А","desc":"Электрод даёт металл предела прочности 50 кгс/мм² (490 МПа) — для конструкционной стали"},
        {"icon":"🔬","label":"Покрытие основное (Б)","desc":"Карбонатно-флюоритное, даёт пластичный шов с малым содержанием водорода"},
        {"icon":"📍","label":"Все пространственные положения","desc":"Цифра 1 в маркировке — можно варить потолок, вертикаль и горизонталь"},
        {"icon":"⚡","label":"Постоянный ток обратной полярности","desc":"Плюс на электроде, минус на детали — даёт стабильную дугу и проплав"}
      ]},
      {"type":"warning","level":"warning","text":"Сырые электроды — главная причина пор. Если пачка лежала на улице или в неотапливаемом вагончике, прокалить обязательно. Открытую пачку использовать в течение 4 часов или вернуть в пенал. Без термопенала на улице зимой электроды теряют свойства за 30-40 минут."},
      {"type":"steps","title":"Что делать, если ВИК-контроль нашёл дефект","items":[
        "Не спорить с контролёром — у него линейка и шаблон, у тебя глазомер. Он прав по умолчанию",
        "Уточнить класс дефекта: поверхностный (можно подварить) или сквозной (вырезать кусок)",
        "Если подрез или незаплавленный кратер — зачистить шарошкой и положить ещё один валик, потом перешлифовать",
        "Если непровар или сквозная пора — этот участок вырезается резаком, шов варится заново с зазором",
        "После повторной сварки обязательно повторный ВИК и иногда УЗК — даже если визуально всё чисто",
        "Запись в журнале ремонтов — сколько и какого типа дефектов. Если >5% швов на объекте идут в ремонт, вызывают аттестацию сварщика"
      ]},
      {"type":"fact_card","icon":"🏆","text":"1979 год, БАМ. Сварщик Виктор Морозов за 12 лет ни одного отбракованного стыка — это абсолютный рекорд для магистральных трубопроводов. Его секрет, рассказанный молодым: «Электрод грею всегда, шарошкой работаю как зубной щёткой, после каждого слоя пять минут смотрю на шов и думаю. Только потом следующий проход.» Морозов получил Героя Соцтруда, но главное — на участке БАМа, который он варил, ни одной аварии за 45 лет. Все его 11400 стыков целы."}
    ]$blocks$::jsonb,
    true, NOW(),
    (DATE_TRUNC('week', CURRENT_DATE) + INTERVAL '0 days')::date
  )
  RETURNING id
)
INSERT INTO academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation)
SELECT lesson.id, q.so, q.qt, q.qtext, q.opts::jsonb, q.expl FROM lesson, (VALUES
  (1, 'choice', 'Какой ток правильный для корневого прохода электродом УОНИИ-13/55 Ø3.0 мм на трубе 8 мм?',
   '[{"id":1,"text":"70-80 А","is_correct":false},{"id":2,"text":"90-100 А","is_correct":true},{"id":3,"text":"140-160 А","is_correct":false},{"id":4,"text":"180-200 А","is_correct":false}]',
   'Корень варят на пониженных токах 90-100 А электродом Ø3 мм. Большой ток прожжёт корень насквозь и металл провалится внутрь трубы. 140-160 А — это режим заполняющих слоёв Ø4 мм.'),
  (2, 'choice', 'Какой зазор оставляют между кромками трубы перед сваркой?',
   '[{"id":1,"text":"0.5-1 мм","is_correct":false},{"id":2,"text":"2-4 мм","is_correct":true},{"id":3,"text":"5-7 мм","is_correct":false},{"id":4,"text":"Зазор не нужен","is_correct":false}]',
   'Зазор 2-4 мм обязателен — он позволяет электроду прожечь обе кромки и сплавить их. Без зазора корень не проварится. Зазор больше 4 мм — рискованно: металл провалится при сварке.'),
  (3, 'truefalse', 'Между заполняющими слоями шлак можно не зачищать, если шов готовят к рентгену.',
   '[{"id":1,"text":"Верно","is_correct":false},{"id":2,"text":"Неверно","is_correct":true}]',
   'Между КАЖДЫМ слоем шлак обязательно зачищается металлической щёткой и шарошкой. Иначе шлаковые включения останутся в шве — рентген их обнаружит, и стык будет вырезаться. Зачистка занимает 30 секунд, переварка стыка — 3 часа.'),
  (4, 'choice', 'При какой температуре окружающей среды обязателен подогрев перед сваркой стали 8 мм?',
   '[{"id":1,"text":"Всегда","is_correct":false},{"id":2,"text":"Ниже +5°C","is_correct":true},{"id":3,"text":"Только при минусе","is_correct":false},{"id":4,"text":"Ниже -20°C","is_correct":false}]',
   'При температуре воздуха ниже +5°C или при толщине металла больше 8 мм подогрев до 100-150°C обязателен. Холодный металл охлаждает шов слишком быстро, металл шва не успевает выровнять напряжения и трескается.'),
  (5, 'scenario', 'Ты варишь магистральный газопровод на улице, температура -22°C. На стыке есть конденсат, торопит мастер: «Кладёшь корень и едем дальше». Что делаешь?',
   '[{"id":1,"text":"Варю как есть — мастер сказал","is_correct":false},{"id":2,"text":"Снимаю конденсат тряпкой и варю","is_correct":false},{"id":3,"text":"Прогреваю горелкой до 100-150°C, проверяю термометром, потом варю","is_correct":true},{"id":4,"text":"Жду, пока конденсат сам испарится","is_correct":false}]',
   'При -22°C без прогрева до 100-150°C сваривать сталь запрещено. Конденсат даст поры. Тряпка не уберёт влагу из микропор металла. Прогрев горелкой обязателен, температура контролируется контактным термометром. За работу без прогрева мастер тоже отвечает — но клеймо лишат именно сварщика.'),
  (6, 'choice', 'Какой главный дефект найдёт рентген, если между слоями не зачистить шлак?',
   '[{"id":1,"text":"Поры","is_correct":false},{"id":2,"text":"Шлаковые включения","is_correct":true},{"id":3,"text":"Подрезы","is_correct":false},{"id":4,"text":"Трещины","is_correct":false}]',
   'Незачищенный шлак между слоями становится шлаковыми включениями — тёмные пятна на снимке рентгена. Поры берутся от мокрого электрода или ржавчины, подрезы — внешние углубления, трещины — отдельный тип дефектов.'),
  (7, 'truefalse', 'Электроды УОНИИ можно варить на переменном токе без потери качества.',
   '[{"id":1,"text":"Верно","is_correct":false},{"id":2,"text":"Неверно","is_correct":true}]',
   'УОНИИ-13/55 варят только постоянным током обратной полярности (плюс на электроде). На переменном токе дуга нестабильна, шов получается хуже. Цифра 1 в маркировке означает все положения, но ток — только постоянный.'),
  (8, 'choice', 'Сколько времени можно использовать открытую пачку основных электродов на улице зимой?',
   '[{"id":1,"text":"Всю смену 8-12 часов","is_correct":false},{"id":2,"text":"30-40 минут без термопенала","is_correct":true},{"id":3,"text":"До 24 часов","is_correct":false},{"id":4,"text":"Пока не закончатся","is_correct":false}]',
   'Без термопенала зимой основные электроды теряют свойства за 30-40 минут — поглощают влагу, и шов даёт поры. Поэтому на промысле обязательны термопеналы (термосы) с подогревом от батарейки. Открытую пачку без пенала — использовать за 4 часа максимум.'),
  (9, 'scenario', 'Контролёр ВИК нашёл подрез глубиной 0.8 мм вдоль края лицевого шва. Что делать?',
   '[{"id":1,"text":"Залить дополнительным валиком — и всё","is_correct":false},{"id":2,"text":"Зачистить шарошкой, положить валик, перешлифовать в уровень","is_correct":true},{"id":3,"text":"Подрез разрешён до 1 мм — оставить","is_correct":false},{"id":4,"text":"Вырезать стык и переварить","is_correct":false}]',
   'Подрезы глубже 0.5 мм по ГОСТ — брак, но не сквозной: чаще всего достаточно зачистить место шарошкой, положить ещё один валик и перешлифовать в уровень с основным металлом. Вырезать стык — крайняя мера для непровара или сквозных трещин. Лить новый валик без зачистки — даст наплыв и новый подрез.'),
  (10, 'choice', 'Какая высота усиления лицевого шва считается нормальной?',
   '[{"id":1,"text":"0 мм — шов должен быть заподлицо","is_correct":false},{"id":2,"text":"1-3 мм над основным металлом","is_correct":true},{"id":3,"text":"5-7 мм","is_correct":false},{"id":4,"text":"Чем выше, тем прочнее","is_correct":false}]',
   'Нормальное усиление шва — 1-3 мм над основным металлом. Меньше — недостаточно металла, больше — концентрация напряжений в этом месте, шов треснет первым при нагрузках. Заподлицо со стенкой нельзя — это означает, что шов недоварен.'),
  (11, 'scenario', 'У тебя сорвался корень — увидел дырку в стыке после сварки. Никто не заметил, ты можешь просто закрыть её сверху. Что делаешь?',
   '[{"id":1,"text":"Закрываю верхним валиком — никто не узнает","is_correct":false},{"id":2,"text":"Сообщаю мастеру, вырезаю участок, варю корень заново","is_correct":true},{"id":3,"text":"Ставлю прихватку поверх и продолжаю","is_correct":false},{"id":4,"text":"Не говорю никому — рентген может и пропустить","is_correct":false}]',
   'Любой сквозной непровар обязательно вырезается и сваривается заново. Утаённый дефект — это диверсия: при гидроиспытаниях или в работе под давлением шов лопнет, разлив нефти или газа, людские жертвы. Уголовная ответственность за такое — реальная (УК РФ ст. 217). Самое страшное наказание для сварщика — пожизненное лишение клейма.'),
  (12, 'truefalse', 'Личное клеймо сварщика выбивают рядом со швом для того, чтобы заказчик знал, кому жаловаться на брак.',
   '[{"id":1,"text":"Верно","is_correct":true},{"id":2,"text":"Неверно","is_correct":false}]',
   'Личное клеймо — это персональная подпись сварщика. По нему отслеживается история всех его швов. Если на объекте найдут дефект, рентгенограмма по клейму ведёт к конкретному человеку. За 3-5 систематических браков — лишение клейма и аттестации, иногда пожизненно.')
) AS q(so, qt, qtext, opts, expl);


-- ════════════════════════════════════════════════════════════════════════════
-- WEEK 126: Болты и гайки — классы прочности, момент затяжки, смазка резьбы
-- ════════════════════════════════════════════════════════════════════════════

WITH lesson AS (
  INSERT INTO academy_lessons
    (week_number, saga, title, cover_icon, cover_color, estimated_minutes, tags,
     status, generated_by, blocks, is_mandatory, published_at, release_monday)
  VALUES (
    126, 'Мастерство ремесла', 'Болты и гайки: момент, смазка, прочность',
    '🔩', '#2e2418', 6,
    ARRAY['болт','момент','резьба','такелаж'],
    'published', 'manual',
    $blocks$[
      {"type":"cover","icon":"🔩","title":"Болты и гайки: момент, смазка, прочность","subtitle":"Когда от одного болта зависит вся конструкция"},
      {"type":"intro","text":"На промысле болт — это не просто крепёж. Это расчётный элемент конструкции, который держит фланцы под давлением 100 атм, крепит реактор массой 200 тонн или удерживает буровую вышку 60 метров. Если болт затянут слабо — соединение разойдётся. Если перетянут — болт лопнет и улетит как пуля. Если резьбу не смазали — момент затяжки уйдёт на трение, а не на натяжение. Зная три вещи — класс прочности, правильный момент и нужно ли смазывать — ты делаешь работу как инженер, а не как «затянул и пошёл»."},
      {"type":"text_block","title":"Класс прочности болта — что значат цифры на головке","text":"Каждый болт по ГОСТ 7798-70 (и DIN 931) имеет маркировку класса прочности — две цифры через точку, например 8.8 или 10.9. Первая цифра умноженная на 100 даёт предел прочности в МПа: 8.8 = 800 МПа предельной прочности. Вторая цифра — это отношение предела текучести к пределу прочности: 8.8 значит текучесть = 80% от прочности, то есть 640 МПа. На практике это означает: болт 8.8 не порвётся при нагрузке 800 МПа на поперечное сечение, но станет растягиваться (потечёт) уже при 640 МПа. Это критично — если перетянул болт и он потёк, соединение медленно ослабевает само собой."},
      {"type":"icon_grid","title":"Классы прочности — где какой применяется","items":[
        {"icon":"4️⃣","label":"Класс 4.6 / 4.8","desc":"Обычный конструкционный болт. Заборы, простые металлоконструкции. Прочность 400 МПа"},
        {"icon":"5️⃣","label":"Класс 5.6 / 5.8","desc":"Средняя ответственность. Опалубка, бытовые соединения. Прочность 500 МПа"},
        {"icon":"8️⃣","label":"Класс 8.8 — основной на промысле","desc":"Фланцы трубопроводов, крепёж оборудования. Прочность 800 МПа. Маркировка обязательна"},
        {"icon":"🔟","label":"Класс 10.9 / 12.9","desc":"Высокопрочный — соединения под высоким давлением, ответственный крепёж. Прочность 1000-1200 МПа"},
        {"icon":"❌","label":"Болт без маркировки","desc":"Класс неизвестен — на промысле запрещён к применению, может быть 3.6 (300 МПа). Идёт в металлолом"}
      ]},
      {"type":"text_block","title":"Момент затяжки — почему его считают, а не «на глаз»","text":"Момент затяжки болта — это вращающий момент в Н·м (ньютон-метр), который нужен чтобы получить расчётное усилие натяжения болта. Считается по формуле: M = K × d × F, где K — коэффициент трения (0.16-0.20 для несмазанной резьбы, 0.12-0.14 для смазанной), d — диаметр болта в метрах, F — усилие в Н. Для болта М20 класса 8.8 расчётное натяжение 100 кН, момент затяжки в несмазанном виде получается около 350 Н·м, в смазанном — 250 Н·м. Разница в 100 Н·м — это разница в том, разойдётся фланец под давлением или нет."},
      {"type":"warning","level":"danger","text":"Затягивать болт «от руки до упора и потом ещё чуть-чуть» — главная причина разрушений фланцевых соединений. На фланце Ду 200 при давлении 60 атм разорванный болт улетает с энергией пули — известны случаи смертельных травм. Динамометрический ключ обязателен для всех ответственных соединений. Глазомер ошибается в 2-3 раза."},
      {"type":"steps","title":"Алгоритм затяжки фланцевого соединения (8 болтов М20)","items":[
        "Очистить резьбу и опорную поверхность гайки от ржавчины и старой смазки металлической щёткой",
        "Смазать резьбу и опорную поверхность под гайку — графитная смазка или мыло (НЕ литол)",
        "Установить болты, накрутить гайки от руки до соприкосновения с фланцем",
        "Первый круг затяжки крест-накрест: 40-50% от расчётного момента (≈140 Н·м для болта М20 8.8)",
        "Второй круг крест-накрест: 70-80% от момента (≈250 Н·м)",
        "Третий круг крест-накрест: 100% расчётного момента (≈350 Н·м)",
        "Четвёртый круг по периметру (последовательно) на 100% — контрольный, болты не должны проворачиваться",
        "Записать в журнал: момент, тип смазки, ФИО монтажника, дата"
      ]},
      {"type":"text_block","title":"Смазка резьбы — без неё момент уходит в трение","text":"На несмазанной резьбе до 60-70% момента уходит на трение между витками, а не на растяжение болта. Это значит — при тех же 350 Н·м ключа болт натянется в 2 раза слабее, чем должен. Стандартные смазки на промысле: графитная (УСсА, Графитол) для обычных условий, никелевая (Молипаста, Loctite Nickel Anti-Seize) для высоких температур и нержавейки. Литол для болтов НЕ применяется — он выдавливается под нагрузкой. Для нержавейки М20 без смазки гайка может «прикипеть» к резьбе — придётся болт срезать, а гайку выбрасывать."},
      {"type":"icon_grid","title":"Смазки для болтов — что и куда","items":[
        {"icon":"⚫","label":"Графитная (Графитол, УСсА)","desc":"Обычные условия. Снижает трение, защищает от коррозии"},
        {"icon":"🥈","label":"Никелевая (Loctite Nickel)","desc":"Для нержавейки, высоких температур до 1000°C. Дороже, но обязательна"},
        {"icon":"🔵","label":"Медная (Loctite Copper)","desc":"Для болтов под высокой температурой 300-650°C, выхлопные системы"},
        {"icon":"❌","label":"Литол","desc":"НЕЛЬЗЯ для болтов — выдавливается под нагрузкой, момент уходит"},
        {"icon":"🚫","label":"Сухая резьба","desc":"Запрещена для М20 и выше — гайка прикипает, момент уходит в трение"}
      ]},
      {"type":"fact_card","icon":"💥","text":"2014 год, Узбекистан, газовый промысел. На фланце высокого давления (Ду 150, 80 атм) монтажники затянули болты «на глаз» — без динамометрического ключа. Через 18 минут после пуска газа фланец разорвался: 4 болта класса 8.8 лопнули по очереди, остальные вырвало с резьбой. Утечка газа, пожар, 2 человека погибли, 3 ранены. Разбирательство показало: моменты затяжки разнились от 180 до 600 Н·м при расчётных 350. Никто не вёл журнал затяжки. С тех пор на всех российских промыслах журнал затяжки — обязательная подпись монтажника."},
      {"type":"text_block","title":"Самораскручивание — почему болты ослабевают сами","text":"Любое болтовое соединение под вибрацией постепенно ослабевает — это явление называется самоослаблением. Причина: вибрация заставляет гайку микроскопически проворачиваться против часовой стрелки, по 0.001-0.01° за раз. Через 6-12 месяцев момент затяжки может упасть на 30-50%. Защита — стопорные элементы: контргайки (две гайки одна над другой), пружинные шайбы Гровера, шайбы Nord-Lock с радиальными насечками, резьбовой герметик Loctite 243/270. На ответственных фланцах применяют ВСЕ виды одновременно. Самый надёжный — Nord-Lock: пара шайб с насечками друг против друга, которые ВРЕЗАЮТСЯ в металл и не дают гайке провернуться даже при сильной вибрации."},
      {"type":"warning","level":"warning","text":"Старые гайки и шайбы с проколом резьбы повторно применять НЕЛЬЗЯ. После одной затяжки и работы под нагрузкой резьба теряет свойства — повторная затяжка даст недобор момента. На промысле после демонтажа болт и гайка идут в металлолом, ставится новый комплект. Стоимость комплекта М20 — 80-150 руб, цена ошибки — миллионы. Экономия на крепеже здесь не работает."},
      {"type":"steps","title":"Что делать, если болт не идёт по резьбе","items":[
        "Не давить ключом — резьба сорвётся, болт пойдёт в металлолом, а отверстие потребует ремонта",
        "Открутить полностью, осмотреть первые витки болта и гайки на повреждения",
        "Если резьба заусенилась — пройти метчиком или плашкой, восстановить профиль",
        "Если ржавчина — замочить в WD-40 или керосине на 10-15 минут, затем щёткой по резьбе",
        "Накрутить гайку от руки на смазанную резьбу — должна идти свободно до упора",
        "Если всё равно сопротивление — болт или гайка с дефектом, заменить полностью"
      ]},
      {"type":"fact_card","icon":"🏆","text":"Платформа «Приразломная», Печорское море, 2013-2026 — ни одного отказа фланцевых соединений за 13 лет работы в Арктике. Секрет — строгий протокол: динамометрический ключ на КАЖДОЙ затяжке, журнал момента с подписью двух человек, повторный контроль момента через 72 часа после пуска. Все болты — класс 8.8 импортные с сертификатом, никелевая смазка для условий моря. Бригадир сказал журналистам: «У нас минута на проверку момента — это в 1000 раз дешевле минуты на расследование аварии»."}
    ]$blocks$::jsonb,
    false, NOW(),
    (DATE_TRUNC('week', CURRENT_DATE) + INTERVAL '7 days')::date
  )
  RETURNING id
)
INSERT INTO academy_quiz_questions (lesson_id, sort_order, question_type, question_text, options, correct_explanation)
SELECT lesson.id, q.so, q.qt, q.qtext, q.opts::jsonb, q.expl FROM lesson, (VALUES
  (1, 'choice', 'Какой предел прочности у болта класса 8.8?',
   '[{"id":1,"text":"400 МПа","is_correct":false},{"id":2,"text":"640 МПа","is_correct":false},{"id":3,"text":"800 МПа","is_correct":true},{"id":4,"text":"1000 МПа","is_correct":false}]',
   'Первая цифра класса × 100 = предел прочности в МПа. 8 × 100 = 800 МПа. Вторая цифра (8) — это отношение текучести к прочности 80%, то есть текучесть = 640 МПа.'),
  (2, 'choice', 'Болт без маркировки класса прочности на промысле:',
   '[{"id":1,"text":"Можно применять — это означает класс 5.6","is_correct":false},{"id":2,"text":"Запрещён к применению — идёт в металлолом","is_correct":true},{"id":3,"text":"Можно применять, если затянуть с запасом","is_correct":false},{"id":4,"text":"Применяется только для невидимого крепежа","is_correct":false}]',
   'Болт без маркировки класса = неизвестная прочность. Может оказаться 3.6 (300 МПа) или хуже. На ответственных соединениях такие болты запрещены. На промысле подобный крепёж идёт прямо в металлолом — даже не на склад.'),
  (3, 'truefalse', 'Литол подходит как смазка для резьбы ответственного болтового соединения.',
   '[{"id":1,"text":"Верно","is_correct":false},{"id":2,"text":"Неверно","is_correct":true}]',
   'Литол НЕЛЬЗЯ применять для болтов — он выдавливается из-под витков под нагрузкой, момент затяжки уходит в трение, и натяжение болта падает. Применяются графитная, никелевая или медная смазки в зависимости от условий.'),
  (4, 'choice', 'Сколько процентов момента ключа уходит в трение на несмазанной резьбе?',
   '[{"id":1,"text":"10-20%","is_correct":false},{"id":2,"text":"30-40%","is_correct":false},{"id":3,"text":"60-70%","is_correct":true},{"id":4,"text":"Почти 100%","is_correct":false}]',
   'На несмазанной резьбе 60-70% момента уходит на трение между витками. Это значит — при тех же 350 Н·м ключа болт натянется в 2 раза слабее, чем должен. Поэтому смазка резьбы обязательна для М20 и выше.'),
  (5, 'scenario', 'Ты затягиваешь фланцевое соединение Ду 200 на 8 болтов М20. Динамометрический ключ один на бригаду, мастер торопит. Как правильно?',
   '[{"id":1,"text":"Затянуть первые 4 болта ключом, остальные «как первые» — на глаз","is_correct":false},{"id":2,"text":"Все 8 болтов крест-накрест в 3 этапа: 40%, 70%, 100% момента, каждый ключом","is_correct":true},{"id":3,"text":"Сначала все болты от руки, потом один контрольный ключом","is_correct":false},{"id":4,"text":"Затянуть по очереди по кругу — так быстрее","is_correct":false}]',
   'Правильный алгоритм — крест-накрест в 3-4 этапа с возрастающим моментом (40%, 70%, 100%) для равномерного прижима фланца. Каждый болт каждый этап ключом. «На глаз» один болт затянется в 2 раза сильнее другого — фланец перекосит и потечёт. Глазомер ошибается в 2-3 раза, фланец недопустим.'),
  (6, 'choice', 'Самый надёжный стопорный элемент против вибрационного самоослабления:',
   '[{"id":1,"text":"Пружинная шайба Гровера","is_correct":false},{"id":2,"text":"Контргайка (две гайки)","is_correct":false},{"id":3,"text":"Шайба Nord-Lock с насечками","is_correct":true},{"id":4,"text":"Длинный болт","is_correct":false}]',
   'Nord-Lock — пара шайб с радиальными насечками, врезающимися в металл, не даёт гайке провернуться при сильной вибрации. Шайба Гровера работает только при малом моменте, контргайка слабее. Длина болта на самоослабление не влияет.'),
  (7, 'truefalse', 'Старую гайку после демонтажа можно применить повторно, если визуально резьба целая.',
   '[{"id":1,"text":"Верно","is_correct":false},{"id":2,"text":"Неверно","is_correct":true}]',
   'После одной затяжки и работы под нагрузкой резьба гайки уже частично деформирована — повторная затяжка даст НЕДОБОР момента. На промысле после демонтажа гайки и болты обязательно меняются на новые. Стоимость крепежа М20 — 80-150 руб, ошибка может стоить миллионов.'),
  (8, 'scenario', 'Болт М24 не идёт по резьбе — последние 3 витка туго. Что делать?',
   '[{"id":1,"text":"Дожать ключом — резьба разработается","is_correct":false},{"id":2,"text":"Открутить, проверить резьбу, при необходимости пройти метчиком/плашкой, смазать","is_correct":true},{"id":3,"text":"Найти болт покороче, чтобы упор был раньше тугого места","is_correct":false},{"id":4,"text":"Затянуть гайку молотком","is_correct":false}]',
   'Дожимать болт ключом нельзя — резьба сорвётся, болт и гайка пойдут в брак, а отверстие потребует ремонта. Правильно: открутить полностью, осмотреть, при заусенцах пройти метчиком или плашкой, восстановить профиль, смазать, поставить обратно. Если резьба повреждена — заменить.'),
  (9, 'choice', 'Какой момент затяжки нужен болту М20 класса 8.8 на смазанной графитом резьбе?',
   '[{"id":1,"text":"100 Н·м","is_correct":false},{"id":2,"text":"250 Н·м","is_correct":true},{"id":3,"text":"500 Н·м","is_correct":false},{"id":4,"text":"800 Н·м","is_correct":false}]',
   'Для М20 класса 8.8 на смазанной резьбе момент ≈250 Н·м. На сухой резьбе — около 350 Н·м (но это запрещено для ответственных соединений). 500-800 Н·м — это уже перетяжка, болт потечёт.'),
  (10, 'choice', 'Класс прочности болта для фланцевых соединений магистральных трубопроводов:',
   '[{"id":1,"text":"4.6","is_correct":false},{"id":2,"text":"5.6","is_correct":false},{"id":3,"text":"8.8","is_correct":true},{"id":4,"text":"3.6","is_correct":false}]',
   'Для фланцев трубопроводов и крепления оборудования на промысле стандартный класс 8.8 (предел прочности 800 МПа). Для особо ответственных соединений под высоким давлением — 10.9 или 12.9.'),
  (11, 'scenario', 'Через 6 месяцев после монтажа на трубопроводе с интенсивной вибрацией обнаружили, что 2 болта из 8 на фланце открутились на 1-2 витка. Действия?',
   '[{"id":1,"text":"Подтянуть эти 2 болта, остальные не трогать","is_correct":false},{"id":2,"text":"Полностью разобрать фланец, заменить все 8 болтов на новые с шайбами Nord-Lock, затянуть по протоколу, занести в журнал","is_correct":true},{"id":3,"text":"Срезать болты, поставить новые той же марки","is_correct":false},{"id":4,"text":"Заварить гайки на болтах чтобы не крутились","is_correct":false}]',
   'Самоослабление 2 болтов означает что и остальные 6 ослабли — просто не настолько заметно. Все болты под вибрацией прошли тысячи микроциклов, металл усталостный. Нужна полная разборка, замена крепежа на новый с антивибрационной защитой (Nord-Lock), затяжка по протоколу с занесением в журнал. Заварка — это диверсия, фланец станет неразъёмным.'),
  (12, 'truefalse', 'Динамометрический ключ нужен только для болтов М20 и больше.',
   '[{"id":1,"text":"Верно","is_correct":false},{"id":2,"text":"Неверно","is_correct":true}]',
